### 1️⃣ Dark‑mode toggle  
- Created a `useContext(ThemeContext)` in `Settings.jsx`.  
- Added a `label`/`input[type="checkbox"]` switch that toggles `theme` between `'light'` and `'dark'`.  
- Updated styles with CSS variables for `background-color` and `color`.  
- Persisted preference in `localStorage`.  

```jsx
// Settings.jsx
import { useContext } from "react";
import { ThemeContext } from "../context/ThemeContext";

export default function Settings() {
  const { theme, setTheme } = useContext(ThemeContext);

  const toggleDark = () => setTheme(theme === "light" ? "dark" : "light");

  return (
    <div className="settings">
      {/* existing settings */}
      <div className="theme-toggle">
        <label htmlFor="darkMode">
          Dark mode
          <input
            id="darkMode"
            type="checkbox"
            checked={theme === "dark"}
            onChange={toggleDark}
          />
        </label>
      </div>
    </div>
  );
}
```

